pub fn parse_price(input: &str) -> Result<u64, String> {
    let (pounds, pence) = input
        .split_once('.')
        .ok_or_else(|| "price must contain a decimal point".to_string())?;
    let pounds_val = pounds
        .parse::<u64>()
        .map_err(|_| "pounds part must be a valid number".to_string())?;
    let pence_val = pence
        .parse::<u64>()
        .map_err(|_| "pence part must be a valid number".to_string())?;
    Ok(pounds_val * 100 + pence_val)
}

